public interface MessageProvider {

    String getMessage();
}

package com.example.demo;

import org.springframework.stereotype.Component;

@Component
public class DefaultMessageProvider implements MessageProvider {

    @Override
    public String getMessage() {
        return "Hello";
    }
}

package com.example.demo;

import org.springframework.stereotype.Service;

@Service
public class GreetingService {

    private final MessageProvider messageProvider;

    public GreetingService(MessageProvider messageProvider) {
        this.messageProvider = messageProvider;
    }

    public String greet(String name) {
        return messageProvider.getMessage() + ", " + name + "!";
    }
}

package com.example.demo;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class GreetingServiceTest {

    @Mock
    private MessageProvider messageProvider;

    @InjectMocks
    private GreetingService greetingService;

    @Test
    void greetUsesMessageFromProvider() {
        given(messageProvider.getMessage()).willReturn("Hi");

        String greeting = greetingService.greet("World");

        assertThat(greeting).isEqualTo("Hi, World!");
        verify(messageProvider).getMessage();
    }
}

package com.example.demo;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.BDDMockito.given;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

@SpringBootTest
class DemoApplicationTests {

    @Autowired
    private GreetingService greetingService;

    @MockitoBean
    private MessageProvider messageProvider;

    @Test
    void contextLoads() {
        assertThat(greetingService).isNotNull();
    }

    @Test
    void greetingUsesStubbedBean() {
        given(messageProvider.getMessage()).willReturn("Welcome");

        assertThat(greetingService.greet("Spring")).isEqualTo("Welcome, Spring!");
    }
}

